using namespace std;

class Solution {
    pair<int, int> evaluate(char op, int v1, int c1, int v2, int c2) {
        if (op == '&') {
            int v = v1 & v2;
            int cost = 1;
            if (v1 == 1 && v2 == 1) cost = min(c1, c2);
            else if (v1 == 0 && v2 == 0) cost = 1 + min(c1, c2);
            return {v, cost};
        } else {
            int v = v1 | v2;
            int cost = 1;
            if (v1 == 0 && v2 == 0) cost = min(c1, c2);
            else if (v1 == 1 && v2 == 1) cost = 1 + min(c1, c2);
            return {v, cost};
        }
    }
public:
    int minOperationsToFlip(string expression) {
        vector<pair<int, int>> valStk;
        vector<char> opStk;

        auto applyOp = [&]() {
            char op = opStk.back(); opStk.pop_back();
            auto [v2, c2] = valStk.back(); valStk.pop_back();
            auto [v1, c1] = valStk.back(); valStk.pop_back();
            valStk.push_back(evaluate(op, v1, c1, v2, c2));
        };

        for (char ch : expression) {
            if (ch == '0' || ch == '1') {
                valStk.push_back({ch - '0', 1});
                if (!opStk.empty() && opStk.back() != '(') {
                    applyOp();
                }
            } else if (ch == '&' || ch == '|') {
                opStk.push_back(ch);
            } else if (ch == '(') {
                opStk.push_back('(');
            } else if (ch == ')') {
                opStk.pop_back();
                if (!opStk.empty() && opStk.back() != '(') {
                    applyOp();
                }
            }
        }
        return valStk[0].second;
    }
};

import java.util.*;

class Solution {
    private int[] evaluate(char op, int v1, int c1, int v2, int c2) {
        if (op == '&') {
            int v = v1 & v2;
            int cost = 1;
            if (v1 == 1 && v2 == 1) cost = Math.min(c1, c2);
            else if (v1 == 0 && v2 == 0) cost = 1 + Math.min(c1, c2);
            return new int[]{v, cost};
        } else {
            int v = v1 | v2;
            int cost = 1;
            if (v1 == 0 && v2 == 0) cost = Math.min(c1, c2);
            else if (v1 == 1 && v2 == 1) cost = 1 + Math.min(c1, c2);
            return new int[]{v, cost};
        }
    }

    public int minOperationsToFlip(String expression) {
        Deque<int[]> valStk = new ArrayDeque<>();
        Deque<Character> opStk = new ArrayDeque<>();

        for (int i = 0; i < expression.length(); ++i) {
            char ch = expression.charAt(i);
            if (ch == '0' || ch == '1') {
                valStk.push(new int[]{ch - '0', 1});
                if (!opStk.isEmpty() && opStk.peek() != '(') {
                    char op = opStk.pop();
                    int[] p2 = valStk.pop();
                    int[] p1 = valStk.pop();
                    valStk.push(evaluate(op, p1[0], p1[1], p2[0], p2[1]));
                }
            } else if (ch == '&' || ch == '|') {
                opStk.push(ch);
            } else if (ch == '(') {
                opStk.push('(');
            } else if (ch == ')') {
                opStk.pop();
                if (!opStk.isEmpty() && opStk.peek() != '(') {
                    char op = opStk.pop();
                    int[] p2 = valStk.pop();
                    int[] p1 = valStk.pop();
                    valStk.push(evaluate(op, p1[0], p1[1], p2[0], p2[1]));
                }
            }
        }
        return valStk.peek()[1];
    }
}

