var minOperationsToFlip = function(expression) {
    function evaluate(op, v1, c1, v2, c2) {
        if (op === '&') {
            const v = v1 & v2;
            let cost = 1;
            if (v1 === 1 && v2 === 1) cost = Math.min(c1, c2);
            else if (v1 === 0 && v2 === 0) cost = 1 + Math.min(c1, c2);
            return [v, cost];
        } else {
            const v = v1 | v2;
            let cost = 1;
            if (v1 === 0 && v2 === 0) cost = Math.min(c1, c2);
            else if (v1 === 1 && v2 === 1) cost = 1 + Math.min(c1, c2);
            return [v, cost];
        }
    }

    const valStk = [];
    const opStk = [];

    const applyOp = () => {
        const op = opStk.pop();
        const [v2, c2] = valStk.pop();
        const [v1, c1] = valStk.pop();
        valStk.push(evaluate(op, v1, c1, v2, c2));
    };

    for (let i = 0; i < expression.length; ++i) {
        const ch = expression[i];
        if (ch === '0' || ch === '1') {
            valStk.push([Number(ch), 1]);
            if (opStk.length > 0 && opStk[opStk.length - 1] !== '(') {
                applyOp();
            }
        } else if (ch === '&' || ch === '|') {
            opStk.push(ch);
        } else if (ch === '(') {
            opStk.push('(');
        } else if (ch === ')') {
            opStk.pop();
            if (opStk.length > 0 && opStk[opStk.length - 1] !== '(') {
                applyOp();
            }
        }
    }
    return valStk[0][1];
